                    load2 = route_load(route2)
                    if load2 + demands[cust] > capacity + 1e-12:
                        continue
                    for ins in range(len(route2) + 1):
                        pre2 = depot_idx if ins == 0 else route2[ins - 1]
                        nex2 = depot_idx if ins == len(route2) else route2[ins]
                        add_delta = dist_idx(pre2, cust) + dist_idx(cust, nex2) - dist_idx(pre2, nex2)
                        delta = remove_delta + add_delta
                        if delta < best_delta - 1e-12 or (abs(delta - best_delta) <= 1e-12 and best_move is not None and (r1, p, r2, ins, ids[cust]) < best_move[0]):
                            best_delta = delta
                            best_move = ((r1, p, r2, ins, ids[cust]), cust)
        if best_move is not None and best_delta < -1e-12:
            (_, p, r2, ins, _), cust = best_move
            # need r1 from tuple
            r1 = best_move[0][0]
            routes_idx[r1].pop(p)
            routes_idx[r2].insert(ins, cust)
            if len(routes_idx[r1]) == 0:
                routes_idx.pop(r1)
            for idx in range(len(routes_idx)):
                routes_idx[idx] = two_opt(routes_idx[idx])
            improved = True

    # remove empty routes if any
    routes_idx = [r for r in routes_idx if len(r) > 0]

    # Convert indices to ids
    routes = []
    for r in routes_idx:
        routes.append([ids[i] for i in r])

    return routes
